#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);
vector<int>indeg(n+1,0),outdeg(n+1,0);
for(int i=0;i<m;++i){int a,b;scanf("%d %d",&a,&b);
++outdeg[a];++indeg[b];}
int judge=-1;
for(int i=1;i<=n;++i)if(indeg[i]==n-1&&outdeg[i]==0){judge=i;break;}
printf("%d\n",judge);return 0;}

